 '1st Shift — 0800-1600':{'aiken, don':'#f65555','brewer, jazmine':'#1c38ec','birdsong, tiffany':'#54ec1c','reese, javontae':'#1caeec','bennett, jasmine':'#bc1cec','cleveland, kenyetta':'#f6c555','small, kendarius':'#55f6e0'},
